SELECT a.APPLICATION_ID, a.APPLICATION_NO, p.FULL_NAME_AR APPLICANT_NAME_AR, o.ORG_NAME_AR FINANCIER_NAME_AR, a.STATUS_CODE, a.APPROVED_FINANCE_AMOUNT, a.TOTAL_SUBSIDY_AMOUNT, sa.APPROVAL_NO SUBSIDY_APPROVAL_NO, sa.APPROVAL_DATE, sa.EXPIRY_DATE, fo.OFFER_NO, fo.EXPIRY_DATE OFFER_EXPIRY_DATE FROM MFF_APPLICATIONS a JOIN MFF_PERSONS p ON p.PERSON_ID = a.PRIMARY_PERSON_ID JOIN MFF_ORGANIZATIONS o ON o.ORG_ID = a.FINANCIER_ID LEFT JOIN MFF_SUBSIDY_APPROVALS sa ON sa.APPLICATION_ID = a.APPLICATION_ID LEFT JOIN MFF_FINANCE_OFFERS fo ON fo.APPLICATION_ID = a.APPLICATION_ID WHERE a.STATUS_CODE IN ('CREDIT_APPROVED','CONDITIONAL_APPROVAL','OFFERED','SUBSIDY_PENDING','CONTRACT_PENDING');
